// The Island's drawn art (src/island/IslandView.tsx): one small SVG for each thing that grows from a seed, in a cozy
// flat style (a dark outline, flat colours, a highlight). 32×32, the ground at the bottom; blocks, floors and walls fill
// the whole cell. Anything without a drawing falls back to its emoji.
import { memo } from 'react';
import { ITEM_BY_ID } from './seeds';

const K = '#3a2a32';
/** Outlined shape. */
const o = (fill: string, w = 1.3) => `fill="${fill}" stroke="${K}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"`;
/** A line in the outline colour (or another). */
const l = (w = 1.2, c = K) => `fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"`;
/** A soft highlight. */
const hi = (op = 0.4) => `fill="#fff" opacity="${op}"`;
/** A shadow on the ground under a thing. */
const shadow = (w = 11) => `<ellipse cx="16" cy="31" rx="${w}" ry="1.6" fill="#000" opacity=".18"/>`;

const lantern = (body: string, rib: string, y = 6) =>
  `<path d="M16 ${y - 4}v3" ${l(1.2)}/><rect x="12" y="${y - 1}" width="8" height="2" rx=".5" ${o('#3f3f46', 1)}/>` +
  `<ellipse cx="16" cy="${y + 7}" rx="7" ry="7.5" ${o(body)}/>` +
  `<path d="M16 ${y - 0.5}v15M11.5 ${y + 1.5}q-2 5.5 0 11M20.5 ${y + 1.5}q2 5.5 0 11" ${l(0.9, rib)}/>` +
  `<ellipse cx="13.5" cy="${y + 4.5}" rx="1.6" ry="2.6" ${hi(0.45)}/><rect x="12" y="${y + 13.5}" width="8" height="2" rx=".5" ${o('#3f3f46', 1)}/>` +
  `<path d="M16 ${y + 15.5}v3" ${l(1.4, '#facc15')}/>`;

const vinyl = (label: string) =>
  `<circle cx="16" cy="16" r="13" ${o('#111827')}/><circle cx="16" cy="16" r="10" ${l(0.6, '#374151')}/><circle cx="16" cy="16" r="7.5" ${l(0.6, '#374151')}/><circle cx="16" cy="16" r="5" fill="${label}" stroke="${K}" stroke-width=".8"/><circle cx="16" cy="16" r="1" fill="${K}"/><path d="M8 9a11 11 0 0 1 6-4" ${l(1.4, '#fff')} opacity=".45"/>`;
const cd = (tint: string) =>
  `<circle cx="16" cy="16" r="13" ${o('#e5e7eb')}/><path d="M16 3a13 13 0 0 1 11 6L16 16z" fill="${tint}" opacity=".55"/><path d="M5 23a13 13 0 0 0 7 5.5L16 16z" fill="#a5f3fc" opacity=".6"/><path d="M27 9a13 13 0 0 1 1.5 9L16 16z" fill="#fde68a" opacity=".6"/><circle cx="16" cy="16" r="4" ${o('#f8fafc', 1)}/><circle cx="16" cy="16" r="1.6" fill="#94a3b8"/>`;
const stairs = (body: string, line: string, top: string) =>
  `<path d="M1 31V24h8v-8h8V9h7V2h7v29z" ${o(body)}/><path d="M1 24h8M9 16h8M17 9h7M24 2h7" ${l(1.6, top)}/><path d="M9 24v7M17 16v15M24 9v22" ${l(0.9, line)}/>`;

/** A refined block: a full cell in one colour, a top highlight, and its pattern. */
const block = (fill: string, light: string, dark: string, pattern: string) =>
  `<rect x="1" y="1" width="30" height="30" rx="2" ${o(fill)}/><path d="M3 3h26" ${l(1.4, light)}/>${pattern.replace(/DARK/g, dark).replace(/LIGHT/g, light)}`;
const bricks = (line: string) => `<path d="M1 11h30M1 21h30M11 1v10M23 11v10M9 21v10M21 1v10M19 21v10" ${l(1.3, line)}/>`;
/** A flame (a torch, a furnace). */
const flame = (x: number, y: number, s = 1) =>
  `<path d="M${x} ${y}c${-3 * s} ${-2 * s} ${-3 * s} ${-6 * s} 0 ${-10 * s}c${0.5 * s} ${3 * s} ${3 * s} ${4 * s} ${2.6 * s} ${7 * s}c-.3 ${2 * s}-1.3 ${3 * s}-2.6 ${3 * s}z" fill="#fb923c" stroke="#9a3412" stroke-width=".8"/><path d="M${x} ${y - 1 * s}c${-1.2 * s} ${-1 * s} ${-1.2 * s} ${-3 * s} 0 ${-4.5 * s}c${0.4 * s} ${1.6 * s} ${1.4 * s} ${2.2 * s} 0 ${4.5 * s}z" fill="#fde047"/>`;

